{
  "name": "CabButton",
  "import": "import { CabButton } from '@eltonbautista/vue'",
  "description": "An arcade-style button with a glossy face that presses into its coloured base. Renders a native `<button>`; use it for actions, not navigation.",
  "props": [
    {
      "name": "variant",
      "type": "\"primary\" | \"secondary\" | \"ghost\"",
      "required": false,
      "default": "\"primary\"",
      "description": "Visual weight. `primary` is the one main action on a view; `secondary` supports it; `ghost` is low emphasis."
    },
    {
      "name": "size",
      "type": "\"md\" | \"sm\" | \"lg\"",
      "required": false,
      "default": "\"md\"",
      "description": "Control size."
    },
    {
      "name": "type",
      "type": "\"button\" | \"submit\" | \"reset\"",
      "required": false,
      "default": "\"button\"",
      "description": "Native button type. Defaults to `button` so it never submits a form by accident."
    },
    {
      "name": "disabled",
      "type": "boolean",
      "required": false,
      "default": "false",
      "description": "Disables the button using the native `disabled` attribute."
    },
    {
      "name": "loading",
      "type": "boolean",
      "required": false,
      "default": "false",
      "description": "Shows a spinner, sets `aria-busy`, and ignores clicks while staying focusable."
    }
  ],
  "types": [],
  "events": [
    {
      "name": "click",
      "type": "[event: MouseEvent]",
      "description": ""
    }
  ],
  "slots": [
    {
      "name": "default",
      "type": "{}",
      "description": ""
    }
  ],
  "a11y": {
    "summary": "An arcade-style button for actions. The glossy face presses down into its coloured base when activated. Use `primary` for the single main action on a view, `secondary` for supporting actions, and `ghost` for low-emphasis ones. Use a link, not a button, for navigation.",
    "pattern": "[WAI-ARIA APG: Button](https://www.w3.org/WAI/ARIA/apg/patterns/button/). Rendered as a native `<button>`, so role, focus and activation come from the browser.",
    "keyboard": "| Key | Action |\n| --- | --- |\n| Tab / Shift+Tab | Moves focus to and from the button. |\n| Enter | Activates the button. |\n| Space | Activates the button. |",
    "focus": "A 3px purple ring (`--cab-color-focus-ring`) with a 3px offset appears on keyboard focus only (`:focus-visible`). A `loading` button stays focusable so focus is never lost mid-action; a `disabled` button is removed from the tab order by the browser.",
    "screenReader": "Announced as \"*label*, button\". While `loading`, `aria-busy=\"true\"` is set and the spinner is hidden from assistive tech, so the label stays the accessible name. Disabled buttons are announced as dimmed/unavailable. Icon-only buttons are not supported: always give the button visible text."
  },
  "examples": [
    {
      "name": "Basic",
      "description": "A primary action button."
    },
    {
      "name": "Variants",
      "description": "All three variants, plus loading and disabled states."
    }
  ]
}

