  "import": "import { CabCheckbox } from '@eltonbautista/vue'",
  "description": "A checkbox for a yes/no choice that is confirmed later (e.g. on form submit). Native `<input type=\"checkbox\">` with a chunky custom box; native semantics are kept.",
  "props": [
    {
      "name": "modelValue",
      "type": "boolean",
      "required": true,
      "description": "Checked state (use `v-model`)."
    },
    {
      "name": "label",
      "type": "string",
      "required": true,
      "description": "Visible label. Clicking it toggles the checkbox."
    },
    {
      "name": "hint",
      "type": "string",
      "required": false,
      "description": "Helper text linked with `aria-describedby`."
    },
    {
      "name": "disabled",
      "type": "boolean",
      "required": false,
      "default": "false",
      "description": "Disables the checkbox."
    }
  ],
  "types": [],
  "events": [
    {
      "name": "update:modelValue",
      "type": "[value: boolean]",
      "description": ""
    }
  ],
  "slots": [],
  "a11y": {
    "summary": "A checkbox for an independent yes/no choice that takes effect later, usually when a form is submitted. For a setting that applies immediately, use `CabSwitch`. Group related checkboxes in a `<fieldset>` with a `<legend>`.",
    "pattern": "[WAI-ARIA APG: Checkbox](https://www.w3.org/WAI/ARIA/apg/patterns/checkbox/), built on a native `<input type=\"checkbox\">` so role, state and form submission come from the browser. The visible box is decorative and hidden from assistive tech.",
    "keyboard": "| Key | Action |\n| --- | --- |\n| Tab / Shift+Tab | Moves focus to and from the checkbox. |\n| Space | Toggles checked state. |",
    "focus": "The 3px purple focus ring is drawn around the visible box (not the hidden input) on keyboard focus. The whole label is a click target, which gives a target well above 24×24px.",
    "screenReader": "Announced as \"*label*, checkbox, checked/not checked\". The hint is linked with `aria-describedby`. The component is controlled: the checked state shown always matches `modelValue`, so a parent that rejects a change never leaves the box out of sync."
  },
  "examples": [
    {
      "name": "Basic",
      "description": "A single checkbox bound with v-model."
    },
    {
      "name": "WithHint",
      "description": "A group of checkboxes inside a fieldset, one with a hint."
    }
  ]
}

